B.ave=new A.cY("borowik_szlachetny","Borowik szlachetny (Prawdziwek)","\u0411\u0435\u043b\u044b\u0439 \u0433\u0440\u0438\u0431 (\u0411\u043e\u0440\u043e\u0432\u0438\u043a)","Boletus edulis","Kr\xf3l Polskich Las\xf3w","Jadalny (Wybitny)",B.T,B.wp,40,B.av1,B.wC,B.wD,15,"Najbardziej poszukiwany grzyb w Polsce. \u017byje w mikoryzie ze starymi sosnami, \u015bwierkami, d\u0119bami i bukami.","Szukaj w ciep\u0142ych, dobrze na\u015bwietlonych borach na granicy mch\xf3w i bor\xf3wczysk 2-4 dni po ulewnych deszczach.",B.ava,!1,"assets/mushrooms/borowik_szlachetny.webp")
